import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cc/ccba.md","filePath":"lezioni/c_analisi/cc/ccba.md"}`),a={name:`lezioni/c_analisi/cc/ccba.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="sul-concetto-di-rappresentazione-di-una-funzione" tabindex="-1">Sul concetto di rappresentazione di una funzione <a class="header-anchor" href="#sul-concetto-di-rappresentazione-di-una-funzione" aria-label="Permalink to “Sul concetto di rappresentazione di una funzione”">​</a></h2><p>È utile ricordare, per ben capire il concetto di funzione, che la funzione è il collegamento esistente fra due variabili, e si può rappresentare, per funzioni reali di variabili reali, mediante il collegamento esistente fra due rette; ora queste rette di solito si rappresentano mediante un sistema di assi ortogonali e la funzione diventa l&#39;insieme dei punti che ad una <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> fanno corrispondere una <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>;</p><blockquote><p>Io, personalmente, trovo un po&#39; riduttiva questa idea di funzione e talvolta ad alcune classi particolarmente brave l&#39;ho spiegata in modo (quasi) equivalente come segue:</p><p>Pensate due rette fra loro parallele, immaginiamo una freccia che ad ogni punto della prima retta mi faccia corrispondere un punto sulla seconda, ed ora immaginiamo di spostare i punti sulla seconda retta (come se fosse di gomma) in modo che ad ogni punto della prima retta stia di fronte il punto corrispondente sulla seconda, in tal caso la funzione sarebbe come vengono &quot;addensati&quot; i punti sulla seconda retta al variare della <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> sulla prima retta; bene, mi dirà qualcuno, ma a cosa serve questo ragionamento?</p><p>Serve a capire che la funzione è qualcosa di più della sua rappresentazione cartesiana: la funzione è un fenomeno (in senso filosofico) che coinvolge i punti dell&#39;asse delle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> (in parole povere è come si addensano i punti sull&#39;asse delle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>) e la curva nel piano cartesiano ne è solamente una rappresentazione grafica.</p></blockquote>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};